from cryptography.hazmat.primitives.ciphers.aead import AESGCM
try:
    import _gcm
except ImportError:
    _gcm = None


class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]; nonce = problem["nonce"]
        pt = problem["plaintext"]; ad = problem["associated_data"] or b""
        if _gcm is not None and len(key) == 16 and len(nonce) == 12:
            ct, tag = _gcm.encrypt(key, nonce, pt, ad, 6)
            return {"ciphertext": ct, "tag": tag}
        c = AESGCM(key).encrypt(nonce, pt, ad)
        return {"ciphertext": c[:-16], "tag": c[-16:]}

