}
static void expand128(aeskey *K, const uint8_t *key){
  __m128i k=_mm_loadu_si128((const __m128i*)key);
  K->nr=10; K->rk[0]=k;
#define R(i,c) k=k128a(k,_mm_aeskeygenassist_si128(k,c)); K->rk[i]=k;
  R(1,1)R(2,2)R(3,4)R(4,8)R(5,16)R(6,32)R(7,64)R(8,128)R(9,27)R(10,54)
