static __m128i gfpow(__m128i h, uint64_t e){ /* h^e, e>=0; returns 1 for e=0 */
  /* 1 in reflected domain: byte-reversed of 0x80 00..: */
  __m128i r; int have=0;
  while(e){ if(e&1){ r = have? gfmul(r,h) : h; have=1;} e>>=1; if(e) h=gfmul(h,h);}
  if(!have){ uint8_t one[16]={0}; one[0]=0x80; r=_mm_shuffle_epi8(_mm_loadu_si128((__m128i*)one),BSWAP);}
  return r;
}

typedef struct {
  const aeskey *K; __m128i Hp[8]; /* Hp[i]=H^(i+1) */
  const uint8_t *nonce; const uint8_t *in; uint8_t *out;
  size_t start_blk, nblk; size_t total_len; /* bytes */
  __m128i result;
} job_t;

static inline __m128i ctrblk(__m128i base, uint32_t c){ return _mm_insert_epi32(base,(int)__builtin_bswap32(c),3); }

static void *worker(void *arg){
  job_t *j=(job_t*)arg; const aeskey *K=j->K;
  __m128i base=_mm_setr_epi32(0,0,0,0);
  memcpy(&base,j->nonce,12);
  uint32_t c=(uint32_t)(2+j->start_blk);
  const uint8_t *in=j->in+16*j->start_blk; uint8_t *out=j->out+16*j->start_blk;
  size_t bytes_end = 16*(j->start_blk+j->nblk); if(bytes_end>j->total_len) bytes_end=j->total_len;
  size_t nbytes = bytes_end-16*j->start_blk;
  size_t nfull = nbytes/16;
  __m128i Y=_mm_setzero_si128();
  size_t i=0;
  const int nr=K->nr;
  for(; i+8<=nfull; i+=8){
    __m128i b[8];
    for(int k=0;k<8;k++) b[k]=_mm_xor_si128(ctrblk(base,c+k),K->rk[0]);
    c+=8;
