    __m128i x0=_mm_xor_si128(Y,_mm_shuffle_epi8(b[0],BSWAP));
    clmul_acc(x0,j->Hp[7],&lo,&mid,&hi);
    for(int k=1;k<8;k++) clmul_acc(_mm_shuffle_epi8(b[k],BSWAP),j->Hp[7-k],&lo,&mid,&hi);
    Y=reduce(lo,mid,hi);
  }
  for(; i<nfull; i++){
    __m128i b=aes_enc1(K,ctrblk(base,c++));
    b=_mm_xor_si128(b,_mm_loadu_si128((const __m128i*)(in+16*i)));
    _mm_storeu_si128((__m128i*)(out+16*i),b);
    Y=gfmul(_mm_xor_si128(Y,_mm_shuffle_epi8(b,BSWAP)),j->Hp[0]);
  }
  size_t rem=nbytes-16*nfull;
  if(rem){
    uint8_t tmp[16]={0}; memcpy(tmp,in+16*i,rem);
    __m128i b=aes_enc1(K,ctrblk(base,c++));
    b=_mm_xor_si128(b,_mm_loadu_si128((const __m128i*)tmp));
    _mm_storeu_si128((__m128i*)tmp,b);
    memcpy(out+16*i,tmp,rem);
    memset(tmp+rem,0,16-rem);
    Y=gfmul(_mm_xor_si128(Y,_mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)tmp),BSWAP)),j->Hp[0]);
  }
  j->result=Y;
  return NULL;
}

static __m128i ghash_buf(__m128i Y, __m128i H, const uint8_t *p, size_t n){
  size_t i=0;
  for(;i+16<=n;i+=16) Y=gfmul(_mm_xor_si128(Y,_mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(p+i)),BSWAP)),H);
  if(i<n){ uint8_t t[16]={0}; memcpy(t,p+i,n-i);
    Y=gfmul(_mm_xor_si128(Y,_mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)t),BSWAP)),H);}
  return Y;
}

