static PyObject *encrypt(PyObject *self, PyObject *args){
  Py_buffer key, nonce, pt, aad; int nthreads;
  if(!PyArg_ParseTuple(args,"y*y*y*y*i",&key,&nonce,&pt,&aad,&nthreads)) return NULL;
  if(key.len!=16 || nonce.len!=12){ PyBuffer_Release(&key);PyBuffer_Release(&nonce);PyBuffer_Release(&pt);PyBuffer_Release(&aad);
    PyErr_SetString(PyExc_ValueError,"unsupported"); return NULL; }
  size_t len=pt.len;
  PyObject *ct=PyBytes_FromStringAndSize(NULL,len);
  PyObject *tagobj=PyBytes_FromStringAndSize(NULL,16);
  if(!ct||!tagobj){ return NULL; }
  uint8_t *out=(uint8_t*)PyBytes_AS_STRING(ct);
