  int T=nthreads; if(T<1)T=1; if(T>MAXT)T=MAXT;
  if(nblk < (size_t)T*4096) T = nblk/4096 ? (int)(nblk/4096) : 1;
  size_t per=(nblk+T-1)/T; per=(per+7)&~(size_t)7;
  int used=0;
  for(int t=0;t<T;t++){
    size_t s=per*t; if(s>=nblk) break;
    size_t n=per; if(s+n>nblk) n=nblk-s;
    job_t *j=&jobs[used]; j->K=&K; memcpy(j->Hp,Hp,sizeof(Hp)); j->nonce=nonce.buf; j->in=pt.buf; j->out=out;
    j->start_blk=s; j->nblk=n; j->total_len=len; used++;
  }
  for(int t=1;t<used;t++) pthread_create(&th[t],NULL,worker,&jobs[t]);
  if(used) worker(&jobs[0]);
  for(int t=1;t<used;t++) pthread_join(th[t],NULL);
